const dialog=document.querySelector('#detail');
window.setTomMotion=(value)=>{reduced=Boolean(value);applyMotion();};
const worlds={
lens:{label:'01 / BEHIND THE LENS',title:'A different<br>way of seeing.',intro:'Wildlife that won’t sit still. The lines of a car. A quiet moment on the water. Photography gives me a reason to look a little longer.',sections:[['What catches my eye','Wildlife and birds, automotive photography, landscapes, and cinematic video. I’m interested in the whole process: finding the moment, getting the shot, and shaping the final edit.'],['In the camera bag','Sony A6700, Tamron 17–70mm, Sigma 10–18mm, and Sony 70–200mm and 200–600mm lenses. Different perspectives, from the wide view to the details you’d otherwise miss.'],['Beyond the still frame','Drone footage with a DJI Mini 4 Pro, action cameras, and an Osmo Pocket 3 open up new ways to tell a story.'],['The edit is part of it','Lightroom and Photoshop are where the image comes together—from choosing the keepers to color, detail, and the final atmosphere.']],tags:'WILDLIFE / AUTOMOTIVE / LANDSCAPE / FILM',footer:'“Taking photos and videos is easy. Turning them into art is where the real work begins.”'},
code:{label:'02 / INSIDE THE CODE',title:'What if I<br>built that?',intro:'A lot of my ideas start with something I wish worked a little differently. Building it is how I find out what’s possible.',sections:[['The foundation','Computer application programming at MVCC, followed by computer science at SUNY Poly. I work across Python, C++, Java, JavaScript, HTML/CSS, and C#.'],['Tools for real interests','Mapping outdoor places, organizing photos, and planning trips. The most interesting software projects tend to connect back to something I already care about.'],['Experiments & side quests','Minecraft servers and plugins, desktop tools, and web interfaces. I like understanding how the pieces connect, then making something of my own.'],['On the workbench','Explore NY, GalleryX, and a cooperative Minecraft island concept. Open the field notes below for the thinking behind each idea.']],tags:'PYTHON / C++ / JAVA / JAVASCRIPT / C#',footer:'Project notes describe interests and work in progress; they aren’t links to released products.'},
outdoors:{label:'03 / OFF THE GRID',title:'Take the<br>long way home.',intro:'Upstate New York is a pretty good place to be curious. Lakes, trails, campsites—and usually a camera somewhere in the bag.',sections:[['On the water','Fishing for bass and pickerel, exploring Delta Lake, and getting out in my 16-foot MirroCraft. There’s always something to learn, fix, or dial in.'],['Into the Adirondacks','Hiking, backpacking, and camping. I like the idea of a good trail, a small camp, and enough time to actually enjoy being there.'],['Pack light. Look closer.','A NEMO Hornet tent, a REI Flash 55 pack, and a camera: a few of the things that bridge my love of the outdoors with making things.'],['The overlap is the point','A trip can become a film. A place can become a map project. An afternoon outside can spark the next thing I want to build.']],tags:'FISHING / BOATING / BACKPACKING / CAMPING',footer:'Favorite setting: somewhere between the water and the woods.'}
};
const projects={explore:{label:'FIELD NOTE 01 / WEB PROJECT',title:'Explore NY.',intro:'A place to connect the dots between “that looks interesting” and actually getting outside.',sections:[['The idea','Bring places, maps, trips, collections, and personal progress into one outdoor exploration experience.'],['The build direction','Next.js, MapLibre, and Supabase—with an interest in official place data, primitive campsites, and lean-tos.']],tags:'MAPS / OUTDOOR DISCOVERY / TRIP PLANNING',footer:'A project in development. This portfolio presents the concept, not a live product demo.'},gallery:{label:'FIELD NOTE 02 / DESKTOP PROJECT',title:'GalleryX.',intro:'A growing photo collection deserves a workflow that makes it easier to find the good stuff.',sections:[['The idea','A desktop gallery for Mac and Windows that can scan external drives and bring photos, exports, and video into a more organized view.'],['The focus','Separate exports, spot duplicates, and make a large media collection easier to explore without losing track of where it lives.']],tags:'PHOTOGRAPHY / DESKTOP TOOLS / MEDIA WORKFLOW',footer:'A project concept and development interest. No download is published here.'},islands:{label:'FIELD NOTE 03 / MINECRAFT CONCEPT',title:'Six islands.<br>One world.',intro:'What happens when progression depends on the people around you?',sections:[['The world','Six islands are divided between one to six players. Players control access to their own islands.'],['The twist','Individual quests and unevenly distributed resources encourage trading and cooperation. Everyone progresses for themselves, but nobody has everything.']],tags:'MINECRAFT / GAME SYSTEMS / COOPERATIVE PLAY',footer:'Game concept. The focus is player-driven cooperation and individual progression.'}};
function showDetail(data){document.querySelector('#detail-content').innerHTML=`<span class="eyebrow">${data.label}</span><h2 class="detail-title" id="detail-heading">${data.title}</h2><p class="detail-intro">${data.intro}</p><div class="detail-tags">${data.tags}</div><div class="detail-grid">${data.sections.map(([title,body])=>`<section><h3>${title}</h3><p>${body}</p></section>`).join('')}</div><p class="detail-footer">${data.footer}</p>`;dialog.setAttribute('aria-labelledby','detail-heading');dialog.showModal();dialog.scrollTop=0;document.body.classList.add('modal-open');}
document.querySelectorAll('[data-world]').forEach(b=>b.addEventListener('click',()=>showDetail(worlds[b.dataset.world])));
document.querySelectorAll('[data-project]').forEach(b=>b.addEventListener('click',()=>showDetail(projects[b.dataset.project])));
document.querySelector('.close-dialog').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>document.body.classList.remove('modal-open'));dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
document.querySelector('#credits').addEventListener('click',()=>showDetail({label:'LANDSCAPE CREDIT',title:'Setting the scene.',intro:'The atmospheric Adirondack landscape used on this site is reference imagery, not a photograph by Tom.',sections:[['Image source','<a href="https://www.wilderwithyou.com/blog/how-to-spend-2-days-in-lake-placid-new-york-the-perfect-weekend-itinerary" target="_blank" rel="noopener noreferrer">Wilder With You — Lake Placid weekend guide ↗</a>']],tags:'ADIRONDACKS / MOUNT JO',footer:'Portfolio text is based on Tom’s interests and project ideas.'}));
const motionButton=document.querySelector('#motion')||document.createElement('button');let reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;try{const saved=sessionStorage.getItem('tom-motion');if(saved!==null)reduced=saved==='off'}catch{}function applyMotion(){document.body.classList.toggle('motion-off',reduced);document.documentElement.style.scrollBehavior=reduced?'auto':'smooth';motionButton.innerHTML=`Motion ${reduced?'off':'on'} <span>${reduced?'○':'◉'}</span>`;motionButton.setAttribute('aria-pressed',String(reduced));motionButton.setAttribute('aria-label',reduced?'Enable animations':'Pause animations');if(reduced)document.querySelector('.hero-photo')?.style.setProperty('transform','none');}applyMotion();motionButton.addEventListener('click',()=>{reduced=!reduced;try{sessionStorage.setItem('tom-motion',reduced?'off':'on')}catch{}applyMotion()});
const observer=new IntersectionObserver(entries=>{entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}})},{threshold:.08});document.querySelectorAll('.reveal').forEach(e=>observer.observe(e));
let scheduled=false;function updateScroll(){const max=document.documentElement.scrollHeight-innerHeight;document.querySelector('.progress').style.width=(max?scrollY/max*100:0)+'%';if(!reduced&&scrollY<innerHeight*1.2&&document.querySelector('.hero-photo'))document.querySelector('.hero-photo').style.transform=`translateY(${scrollY*.2}px) scale(1.03)`;scheduled=false;}addEventListener('scroll',()=>{if(!scheduled){requestAnimationFrame(updateScroll);scheduled=true}},{passive:true});updateScroll();
